function ic(name,size){return '<svg class="nav-icon" aria-hidden="true" width="'+(size||18)+'" height="'+(size||18)+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+(PATHS[name]||PATHS.grid)+'</svg>'}
function esc(str){return String(str==null?"":str).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]})}
function money(num){return "KES "+Number(num||0).toLocaleString("en-KE")}
