function restore(){try{var o=JSON.parse(localStorage.getItem(VERSION));return o&&Array.isArray(o.bookings)&&Array.isArray(o.vehicles)?o:JSON.parse(JSON.stringify(seed))}catch(e){return JSON.parse(JSON.stringify(seed))}}
