function def(){return PORTALS.find(function(p){return p.id===state.portal})||PORTALS[2]}
function vehicle(id){return db.vehicles.find(function(v){return v.id===id})||db.vehicles[0]}
function button(label,action,kind,extra){return '<button type="button" class="button '+(kind||"secondary")+'" data-action="'+action+'" '+(extra||"")+'>'+label+'</button>'}
function tag(value){var s=String(value).toLowerCase(),cls=/completed|paid|available|active|verified|confirmed|ready/i.test(s)?"success":/awaiting|pending|maintenance|review|hold|due/i.test(s)?"warn":/cancel|reject|fail|overdue/i.test(s)?"error":"info";return '<span class="pill '+cls+'"><span class="dot" style="width:5px;height:5px"></span>'+esc(value)+'</span>'}
