function navIcon(name){if(/overview|insight|reports|revenue|analytics/i.test(name))return "grid";if(/booking|reserv|operation|schedule|availab|trip|request/i.test(name))return "calendar";if(/fleet|vehicle|rental|car/i.test(name))return "car";if(/payment|finance|invoice|earning|payout|settle|subscription|commission|pricing|rate/i.test(name))return "wallet";if(/customer|driver|owner|team|employee|companies|leads|partner|profile|agent|approv/i.test(name))return "users";if(/website|studio|discover|explore|home|service/i.test(name))return "globe";if(/security|compliance|document|agreement/i.test(name))return "shield";if(/maintenance|inspection|work order|job/i.test(name))return "wrench";if(/settings|config/i.test(name))return "sliders";return "file"}
function header(title,desc,actionLabel,action){return '<div class="page-heading"><div><span class="eyebrow">'+esc(def().kind)+' WORKSPACE · TUESDAY, 13 OCT 2026</span><h1>'+esc(title)+'</h1><p class="muted">'+esc(desc)+'</p></div><div class="heading-actions">'+button(ic("download",16)+" Guide","guide","secondary")+button(ic("plus",16)+" "+esc(actionLabel||"New booking"),action||"new-booking","primary")+'</div></div>'}
function demo(){return '<div class="demo-strip">'+ic("info",17)+'<span><strong>Interactive demo</strong> · Sample people, vehicles and payments. Changes stay in this browser; no backend, authentication, financial transfers or live bookings.</span><button class="text-link" style="margin-left:auto" data-action="reset">Reset demo</button></div>'}
function stat(label,value,detail,icon,trend){return '<div class="card stat"><div class="stat-top"><span class="stat-label">'+esc(label)+'</span><span class="stat-icon">'+ic(icon,18)+'</span></div><div class="stat-value mono">'+value+'</div><div class="stat-bottom">'+(trend?'<span class="trend">'+esc(trend)+'</span> · ':"")+esc(detail)+'</div></div>'}
function headCard(title,sub,link,action){return '<div class="card-header"><div><h2>'+esc(title)+'</h2><p>'+esc(sub)+'</p></div>'+(link?'<button class="text-link" data-action="'+action+'">'+esc(link)+' →</button>':"")+'</div>'}
function taskRows(){return db.bookings.slice(0,5).map(function(b){var v=vehicle(b.vehicle),verb=b.status==="Awaiting payment"?"Record payment":b.status==="Confirmed"?"Handover":b.status==="Active"?"Return":"Details";return '<div class="task-row"><div class="task-initial '+(b.status==="Awaiting payment"?"orange":b.status==="Active"?"purple":"")+'">'+esc(b.customer.split(" ").map(function(x){return x[0]}).slice(0,2).join(""))+'</div><div class="task-details"><strong>'+esc(b.customer)+' · '+esc(v.name)+'</strong><small>'+esc(b.id)+' · '+esc(b.date)+' · '+esc(b.days)+' day(s)</small></div><div>'+tag(b.status)+'</div><button class="mini-action" data-action="booking-action" data-id="'+esc(b.id)+'">'+verb+'</button></div>'}).join("")}
function attention(){return '<div class="attention-list">'+[
 ["alert","Payment needs attention","Grace Njeri’s reservation has not been paid.","Bookings"],
 ["wrench","Vehicle servicing due","Toyota RAV4 is in maintenance; keep it unavailable.","Fleet"],
 ["shield","Document review","Two sample compliance records need your review.","Inspections"],
 ["wallet","Owner payouts awaiting review","Approve settlements only after reconciliation.","Owner settlements"]
].map(function(a,i){return '<div class="attention-item"><div class="attention-icon '+(i===2?"blue":i===3?"green":"")+'">'+ic(a[0],16)+'</div><div class="attention-copy"><b>'+esc(a[1])+'</b><p>'+esc(a[2])+'</p><button class="text-link" data-action="nav" data-value="'+esc(a[3])+'">Review now →</button></div></div>'}).join("")+'</div>'}
function carCard(v){return '<div class="vehicle-card"><div class="vehicle-visual '+(v.status==="Available"?"green":"blue")+'">'+vehicleSvg(v.color)+'</div><div style="display:flex;align-items:center;justify-content:space-between;gap:7px"><h3>'+esc(v.name)+'</h3>'+tag(v.status)+'</div><div class="vehicle-meta">'+esc(v.plate)+' · '+esc(v.type)+' · '+esc(v.location)+'</div><div class="vehicle-foot"><span class="price">'+money(v.rate)+'<small> / day</small></span><button class="text-link" data-action="vehicle" data-id="'+esc(v.id)+'">Details →</button></div></div>'}
function chart(){var heights=[40,58,49,68,62,83,75,95,72,88,97,85];return '<div class="card chart-card"><div class="chart-top"><div><h2>Rental activity</h2><p class="muted tiny">Illustrative bookings trend</p></div><span class="pill">Last 12 months</span></div><div class="chart">'+heights.map(function(v,i){return '<div class="bar-wrap"><div class="bar '+(i===10?"accent":"")+'" style="height:'+v+'%"></div></div>'}).join("")+'</div><div class="chart-x">Jan <span>Mar</span><span>May</span><span>Jul</span><span>Sep</span> Dec</div><div class="chart-key" style="margin-top:17px">'+tag("Illustrative data")+' · No real analytics are connected.</div></div>'}
function companyOverview(){var active=db.bookings.filter(function(b){return b.status==="Active"}).length;var upcoming=db.bookings.filter(function(b){return b.status==="Confirmed"}).length;var due=db.bookings.filter(function(b){return b.status==="Awaiting payment"}).length;var revenue=db.bookings.filter(function(b){return b.status==="Active"||b.status==="Completed"}).reduce(function(s,b){return s+b.total},0);
return header("Good afternoon, team","Your operations are moving. Here’s what needs your attention.","New booking","new-booking")+demo()+
'<div class="grid kpis">'+stat("Active rentals",active,"Vehicles currently with renters","car","+ live operations")+stat("Upcoming handovers",upcoming,"Confirmed reservations","calendar","Next 48 hours")+stat("Payments to follow up",due,"Reservations awaiting payment","wallet","Needs action")+stat("Example rental value",money(revenue),"Active + completed sample bookings","chart","Demo values")+'</div>'+
'<div class="grid two-columns"><section class="card">'+headCard("Today's operations","Follow each rental from reservation to return","View bookings","bookings")+'<div class="task-list">'+taskRows()+'</div></section><section class="card">'+headCard("Needs your attention","Priority items across the business") +attention()+'</section></div>'+
'<div class="section-lead"><div><h2>Fleet snapshot</h2><p>The vehicles and their operational readiness</p></div><button class="text-link" data-action="nav" data-value="Fleet">Go to fleet →</button></div><div class="grid three-columns" style="margin-bottom:21px">'+db.vehicles.slice(0,3).map(carCard).join("")+'</div>'+
'<div class="grid two-columns">'+chart()+'<div class="card">'+headCard("Quick actions","Start where the work is")+'<div class="quick-actions">'+quickBtn("New reservation","new-booking","calendar")+quickBtn("Fleet availability","availability","car")+quickBtn("Record a payment","bookings","wallet")+quickBtn("View settlements","settlements","chart")+quickBtn("Try another portal","switcher","layers")+'</div>'+headCard("Designed around actions","A clear next step for every operational state")+'<div style="padding:0 22px 22px" class="muted tiny">This workspace is a visual frontend prototype. You can complete a mock payment, handover and return without involving a real rental or bank account.</div></div></div>'}
function quickBtn(label,act,icon){return '<button class="quick-button" data-action="'+act+'">'+ic(icon,17)+esc(label)+ic("arrow",12)+'</button>'}
function bookingTable(mode){var items=db.bookings.filter(function(b){return mode==="Rentals"?b.status==="Active"||b.status==="Completed":true});return '<div class="card table-card">'+headCard(mode==="Rentals"?"Rental register":"Reservation register",mode==="Rentals"?"Rentals in progress and closed rentals":"Payments, handovers and return status in one view")+'<div class="table-toolbar"><div class="search-field">'+ic("search",15)+'<input type="search" id="table-search" placeholder="Search customer, vehicle, ID…" aria-label="Filter reservations"></div><span class="pill">'+items.length+' demo records</span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Vehicle</th><th>Pickup</th><th>Amount</th><th>Status</th><th>Next action</th></tr></thead><tbody id="records-body">'+items.map(function(b){var v=vehicle(b.vehicle),act=b.status==="Awaiting payment"?"Record payment":b.status==="Confirmed"?"Handover":b.status==="Active"?"Return vehicle":"Review";return '<tr data-search="'+esc((b.id+" "+b.customer+" "+v.name).toLowerCase())+'"><td><span class="row-title">'+esc(b.id)+'</span><div class="row-secondary">'+esc(b.channel)+'</div></td><td>'+esc(b.customer)+'</td><td><span class="row-title">'+esc(v.name)+'</span><div class="row-secondary">'+esc(v.plate)+'</div></td><td>'+esc(b.date)+'</td><td class="mono">'+money(b.total)+'</td><td>'+tag(b.status)+'</td><td><button class="mini-action" data-action="booking-action" data-id="'+esc(b.id)+'">'+esc(act)+' →</button></td></tr>'}).join("")+'</tbody></table></div></div>'}
function fleet(){return '<div class="section-lead"><div><h2>All vehicles</h2><p>Every asset, readiness status and ownership in one place</p></div><span class="pill">'+db.vehicles.length+' demo vehicles</span></div><div class="grid listing-grid">'+db.vehicles.map(carCard).join("")+'</div><div class="notice" style="margin-top:21px">'+ic("shield",22)+'<div><strong>Readiness means more than an open calendar</strong><p>A production rental can only be booked when its compliance, inspection and allocation rules allow it. This demo does not enforce all backend rules.</p></div></div>'}
function availability(){return '<div class="card">'+headCard("Vehicle availability","Visual readiness board · 13–19 October 2026")+'<div class="table-wrap"><table><thead><tr><th>Vehicle</th><th>Base</th><th>Today</th><th>Wed 14</th><th>Thu 15</th><th>Fri 16</th><th>Sat 17</th></tr></thead><tbody>'+db.vehicles.map(function(v,i){return '<tr><td><span class="row-title">'+esc(v.name)+'</span><div class="row-secondary">'+esc(v.plate)+'</div></td><td>'+esc(v.location)+'</td>'+[0,1,2,3,4].map(function(n){return '<td>'+tag(v.status==="Maintenance"?"Blocked":v.status==="On rental"&&n<2?"On rental":i===0&&n===1?"Reserved":"Available")+'</td>'}).join("")+'</tr>'}).join("")+'</tbody></table></div></div><div class="notice" style="margin-top:18px">'+ic("info",20)+'<div><strong>Calendar representation is illustrative</strong><p>Conflicts, buffers, branch transfers, holds and compliance enforcement will be implemented when the new UI is married to the backend.</p></div></div>'}
function settlements(){return '<div class="card table-card">'+headCard("Owner settlements","Demo approval and payout tracking")+'<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Vehicle owner</th><th>Vehicle</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>'+db.payouts.map(function(p){return '<tr><td class="row-title">'+esc(p.id)+'</td><td>'+esc(p.owner)+'</td><td>'+esc(p.vehicle)+'</td><td class="mono">'+money(p.amount)+'</td><td>'+tag(p.status)+'</td><td>'+(p.status==="Pending"?'<button class="mini-action" data-action="payout" data-id="'+esc(p.id)+'">Mark demo paid →</button>':'<span class="muted tiny">Recorded</span>')+'</td></tr>'}).join("")+'</tbody></table></div></div><div class="demo-strip" style="margin-top:18px">This simulates a payout status change only. No cash movement or actual reconciliation occurs.</div>'}
function finance(){var unpaid=db.bookings.filter(function(b){return b.status==="Awaiting payment"});return '<div class="grid kpis">'+stat("Unpaid reservations",unpaid.length,"Payment follow-ups","wallet")+stat("Sample booking value",money(db.bookings.reduce(function(s,b){return s+b.total},0)),"Not real business revenue","chart")+stat("Pending settlements",db.payouts.filter(function(x){return x.status==="Pending"}).length,"Not transferred","users")+stat("Demo deposits",money(0),"No simulated deposits","shield")+'</div>'+bookingTable("Bookings")}
function companyCtx(){return {db:db,state:state,save:save,render:render,navigate:navigate,showToast:showToast,esc:esc,ic:ic,money:money,tag:tag,vehicle:vehicle,vehicleSvg:vehicleSvg,header:header,demo:demo,button:button,stat:stat,bookingTable:bookingTable}}
function companyPage(){var page=state.page;if(window.SageGapV2){var gap=window.SageGapV2.companyPage(companyCtx());if(gap!==null)return gap;}if(window.SageExternalV2&&window.SageExternalV2.renderCompany){var inbox=window.SageExternalV2.renderCompany(companyCtx());if(inbox!==null)return inbox;}if(window.SageCompanyV2){var special=window.SageCompanyV2.renderPage(page,companyCtx());if(special!==null)return special;}if(page==="Overview"||page==="Today's operations")return companyOverview();var t={
 Bookings:["Bookings","All reservations and their next operational steps","New booking","new-booking"],
 Rentals:["Rental operations","Manage vehicles that have been handed over","New booking","new-booking"],
 Fleet:["Fleet management","Assets, ownership and operational readiness","View availability","availability"],
 Availability:["Availability planner","See every vehicle before narrowing to a specific one","New booking","new-booking"],
 "Finance & payments":["Finance & payments","Reconcile money without losing the rental context","View settlements","settlements"],
 "Owner settlements":["Owner settlements","Transparent earnings, calculations and payouts","View finance","finance"]
};
if(t[page]){var c=t[page];return header(c[0],c[1],c[2],c[3])+demo()+(page==="Bookings"||page==="Rentals"?bookingTable(page):page==="Fleet"?fleet():page==="Availability"?availability():page==="Owner settlements"?settlements():finance())}
return modulePage()}
