 "Pricing":[["Base rate plans","Vehicle category and time-based pricing","Fleet"],["Offers and promotions","Promotions with validity rules","Bookings"],["Quotation preview","Understand final price composition","Bookings"]],
 "Business insights":[["Fleet utilization","Track asset use and idle time","Availability"],["Revenue analysis","See what contributes to earnings","Finance & payments"],["Owner performance","Cost and settlement insights","Owner settlements"]],
