 "Company & branches":[["Company details","Business profile, locations and tax data","Settings"],["Branch capacity","Locations, employees and vehicles","Fleet"],["Opening hours","Pickup, return and operating schedules","Availability"]],
 "Team & permissions":[["Staff directory","Create and manage role assignments","Settings"],["Branch access","Permissions by assigned location","Company & branches"],["Activity history","Accountability and security log","Settings"]],
 "Settings":[["Integrations","Payment, email and notification channels","Finance & payments"],["Subscription","Entitlements and billing","Company & branches"],["Audit & privacy","Access history and controls","Team & permissions"]]
